#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Embed the 320 x 240 HDSLAVE screen art. Run: python3 tools/hdslave_art.py FLARE.png"""
from pathlib import Path
import sys

from boot_art import image_chunks, literal


def main(path):
    png = image_chunks(path)
    out = Path(__file__).resolve().parents[1] / "src/melodee/ui/hdslave_flare.h"
    out.write_text(
        "// SPDX-License-Identifier: LicenseRef-Hdslave-Flare\n"
        "// Copyright (C) 2026 hdslave. All rights reserved. See THIRD_PARTY.md, HDSLAVE screen art.\n"
        "// Generated by tools/hdslave_art.py.\n"
        "#pragma once\n\nnamespace melodee::ui {\n\n"
        + literal("hdslave_flare_png", png, "Static screen backdrop")
        + "\n} // namespace melodee::ui\n"
    )


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    main(sys.argv[1])
